func (c *Client) ListRepositories(ctx context.Context, sort RepositorySort) ([]Repository, error) {
	path := "/api/v1/repositories"
	if sort != "" {
		path += "?" + url.Values{"sort": []string{string(sort)}}.Encode()
	}

	resp, err := c.Get(ctx, path)
	if err != nil {
